from pydantic import BaseModel
from typing import Dict, Optional, Any, List
from schemas import options_schemas


class RequestSearchByImageQuery(BaseModel):
    image_base64: str
    dataset: Optional[options_schemas.DatasetOptions] = options_schemas.DatasetOptions.option1
    model: options_schemas.ModelOptions
    display_window_size: int = 0

    class Config:
        json_schema_extra = {
            "example": {
                    "image_base64": """data:image/jpeg;base64,""",
                    "dataset": "lsc24",
                    "model": "clips",
                    "display_window_size": 0
            }
        }


class RequestSearchByTextQuery(BaseModel):
    text_query: str
    dataset: options_schemas.DatasetOptions = options_schemas.DatasetOptions.option1
    model: options_schemas.ModelOptions
    use_temporal_window: bool = True
    temporal_window_size: int = 3
    display_window_size: int = 0
    subset_record_ids: Optional[List[int]] = []
    object_global_encoding: Optional[Dict[str, int]] = {}
    object_local_encoding: Optional[str] = ""
    color_global_encoding: Optional[Dict[str, int]] = {}
    color_local_encoding: Optional[str] = ""
    pose_local_encoding: Optional[str] = ""
    user_id: Optional[str] = "default"
    query_id: Optional[str] = "default"

    class Config:
        json_schema_extra = {
            "example": {
                    "text_query": "a man walking in the park -d 2019-01-08 -l park -a computer | a house",
                    "dataset": "lsc24",
                    "model": "clips",
                    "use_temporal_window": False,
                    "temporal_window_size": 3,
                    "display_window_size": 0,
                    "user_id": "rhymastic",
                    "query_id": "LSC25-xxx"
            }
        }


class QueryClause(BaseModel):
    text: str  # still required
    filters: Dict[str, Any] = {}  # dynamically loaded filters (e.g., date, location)


class QueryStructured(BaseModel):
    clauses: List[QueryClause]
    dataset: options_schemas.DatasetOptions
    model: options_schemas.ModelOptions
    use_temporal_window: bool = True
    temporal_window_size: int = 3
    display_window_size: int = 5
    subset_record_ids: Optional[List[int]] = []
    object_global_encoding: Optional[Dict[str, int]] = {}
    object_local_encoding: Optional[str] = ""
    color_global_encoding: Optional[Dict[str, int]] = {}
    color_local_encoding: Optional[str] = ""
    pose_local_encoding: Optional[str] = ""

    class Config:
        json_schema_extra = {
            "example": {
                "query": [
                    {
                        "text": "a man walking in the park",
                        "filters": {
                            "date": "2019-01-08",
                            "location": "park"
                        }
                    }
                ],
                "dataset": "lsc24",
                "model": "clips",
                "use_temporal_window": True,
                "temporal_window_size": 3,
                "display_window_size": 3
            }
        }


class RequestExploreSimilarImages(BaseModel):
    image_urls: list[str]
    dataset: options_schemas.DatasetOptions
    model: options_schemas.ModelOptions
    display_window_size: int = 0
    user_id: Optional[str] = "default"
    query_id: Optional[str] = "default"

    class Config:
        json_schema_extra = {
            "example": {
                    "image_urls": [
                        "http://10.0.1.21:20716/201910/31/20191031_065919_000.jpg",
                        "http://10.0.1.21:20716/201910/31/20191031_070027_000.jpg"
                    ],
                    "dataset": "lsc24",
                    "model": "clips",
                    "user_id": "rhymastic",
                    "query_id": "LSC25-xxx"
            }
        }


class RequestExploreNeighborImages(BaseModel):
    image_url: str
    dataset: options_schemas.DatasetOptions
    span: int
    display_window_size: int = 0
    user_id: Optional[str] = "default"
    query_id: Optional[str] = "default"

    class Config:
        json_schema_extra = {
            "example": {
                    "image_url": "http://10.0.1.21:20716/201910/31/20191031_070027_000.jpg",
                    "dataset": "lsc24",
                    "span": 30,
                    "user_id": "rhymastic",
                    "query_id": "LSC25-xxx"
            }
        }


class RequestFeedbackRelevant(BaseModel):
    ids: list[int]
    prior_scores: list[float]
    limit: int

class RequestFeedbackIrrelevant(BaseModel):
    ids: list[int]
    limit: int

class RequestFeedback(BaseModel):
    like: RequestFeedbackRelevant
    dislike: RequestFeedbackIrrelevant
    model: options_schemas.ModelOptions
    dataset: Optional[options_schemas.DatasetOptions] = options_schemas.DatasetOptions.option1

    class Config:
        json_schema_extra = {
            "example": {
                "like": {
                    "ids": [100000, 100001, 100002],
                    "prior_scores": [0.9, 0.8, 0.7],
                    "limit": 5
                },
                "dislike": {
                    "ids": [200000, 200001, 200002],
                    "limit": 5
                },
                "model": "clips",
                "dataset": "lsc24"
            }
        }
